import { useState, useEffect } from 'react';
import MapContainerComponent from './components/Map/MapContainer';
import Dashboard from './components/Dashboard/Dashboard';
import RiskMindmap from './components/Mindmap/RiskMindmap';
import FloatingChat from './components/Chat/FloatingChat';
import { Rnd } from 'react-rnd';
import { ChevronRight, ChevronLeft } from 'lucide-react';

const API_URL = import.meta.env.VITE_API_URL || "http://localhost:8000";

function App() {
  const [isDashboardMinimized, setIsDashboardMinimized] = useState(false);
  const [districts, setDistricts] = useState([]);
  const [selectedDistrictId, setSelectedDistrictId] = useState(null);
  const [fires, setFires] = useState([]);
  const [showMindmap, setShowMindmap] = useState(true);
  const [windGrid, setWindGrid] = useState([]);
  const [showWind, setShowWind] = useState(true);

  useEffect(() => {
    if (selectedDistrictId) {
      setShowMindmap(true);
    }
  }, [selectedDistrictId]);

  useEffect(() => {
    // Fetch mock data
    fetch(`${API_URL}/api/observations?t=${Date.now()}`)
      .then(res => res.json())
      .then(data => {
        setDistricts(data.observations);
      })
      .catch(err => console.error("Error fetching data", err));


    fetch(`${API_URL}/api/fires?confidence=nominal&timeframe_hours=120&t=${Date.now()}`)
      .then(res => res.json())
      .then(data => {
        console.log("Raw Fire API Response:", data);
        setFires(data.fires || []);
      })
      .catch(err => console.error("Error fetching fires", err));

    fetch(`${API_URL}/api/wind_grid`)
      .then(res => res.json())
      .then(data => setWindGrid(data.grid || []))
      .catch(err => console.error("Error fetching wind grid", err));
  }, []);

  const selectedDistrict = districts.find(d => d.district_id === selectedDistrictId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-zinc-950 text-zinc-50 font-sans relative">
      <div className="absolute inset-0 z-0">
         <MapContainerComponent 
           districts={districts} 
           fires={fires}
           windGrid={windGrid}
           showWind={showWind}
           onSelectDistrict={setSelectedDistrictId}
           selectedDistrictId={selectedDistrictId}
         />
         <div className="absolute top-6 left-6 z-[1000] glass-panel px-1.5 py-1.5 rounded-2xl flex items-center shadow-2xl border border-white/5">
           <button 
             onClick={() => setShowWind(!showWind)}
             className={`px-5 py-2.5 rounded-xl font-bold transition-all duration-300 text-xs tracking-widest uppercase flex items-center gap-2 ${
               showWind 
                 ? 'bg-blue-600/90 text-white shadow-[0_0_20px_rgba(37,99,235,0.6)] border border-blue-500/50' 
                 : 'bg-transparent text-zinc-400 hover:text-white hover:bg-white/5 border border-transparent'
             }`}
           >
             <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12.8 19.6A2 2 0 1 0 14 16H2"/><path d="M17.5 8a2.5 2.5 0 1 0 2-4H2"/><path d="M9.8 8.6A2 2 0 1 1 11 12H2"/></svg>
             Wind Layer
           </button>
         </div>
      </div>

      {/* Floating Tactical Sidebar */}
      <div className={`absolute top-4 bottom-4 right-4 z-10 flex flex-col glass-panel rounded-3xl overflow-hidden transition-all duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] ${isDashboardMinimized ? 'w-0 opacity-0 pointer-events-none translate-x-12' : 'w-[480px] opacity-100 shadow-[0_0_40px_rgba(0,0,0,0.8)] border border-white/10 translate-x-0'}`}>
         <div className="p-6 w-full h-full overflow-y-auto custom-scrollbar">
            <Dashboard districts={districts} selectedDistrict={selectedDistrict} onClose={() => setSelectedDistrictId(null)} />
         </div>
      </div>

      {/* Sidebar Toggle */}
      <button 
         onClick={() => setIsDashboardMinimized(!isDashboardMinimized)}
         className={`absolute top-1/2 transition-all duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] transform -translate-y-1/2 bg-zinc-900/90 p-3 rounded-full border border-white/10 text-white z-50 shadow-[0_0_20px_rgba(0,0,0,0.5)] hover:scale-110 hover:bg-zinc-800 backdrop-blur-md ${isDashboardMinimized ? 'right-6' : 'right-[466px]'}`}
       >
         {isDashboardMinimized ? <ChevronLeft size={20} className="text-blue-400 drop-shadow-[0_0_8px_rgba(96,165,250,0.8)]" /> : <ChevronRight size={20} className="text-zinc-400" />}
       </button>
      {selectedDistrict && showMindmap && (
        <Rnd
          default={{
            x: 20,
            y: 20,
            width: 500,
            height: 400,
          }}
          minWidth={300}
          minHeight={200}
          bounds="window"
          className="z-50 rounded-2xl shadow-[0_0_40px_rgba(0,0,0,0.8)] border border-white/10 glass-panel overflow-hidden"
          dragHandleClassName="drag-handle"
          style={{ display: 'flex', flexDirection: 'column' }}
        >
          <div className="drag-handle bg-zinc-900/50 px-5 py-3 cursor-move flex items-center justify-between border-b border-white/10 backdrop-blur-md">
            <h3 className="font-bold text-xs uppercase tracking-widest text-zinc-300">Tactical Mindmap</h3>
            <div className="flex gap-2">
              <button 
                onClick={() => setShowMindmap(false)} 
                className="w-4 h-4 rounded-full bg-red-500 flex items-center justify-center hover:bg-red-400 text-slate-900 transition-colors"
                title="Close"
              >
                <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
              </button>
            </div>
          </div>
          <div style={{ flex: 1, position: 'relative', minHeight: 0 }}>
            <RiskMindmap district={selectedDistrict} />
          </div>
        </Rnd>
      )}
      <FloatingChat />
    </div>
  );
}

export default App;

import os
from dotenv import load_dotenv
load_dotenv()

from fastapi import FastAPI, Response
from fastapi.middleware.cors import CORSMiddleware
from datetime import datetime
import uuid
import random
import requests
from pydantic import BaseModel
from typing import List

app = FastAPI(title="SteppeGuard API", version="1.0.0")

# Allow CORS for frontend (Vercel)
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"], # Allows Vercel to connect safely
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

@app.get("/api/observations")
def get_observations(response: Response = None, district_id: str = None, limit: int = 50, since_hours: int = 24):
    if response:
        response.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    supabase_url = os.getenv("SUPABASE_URL")
    supabase_key = os.getenv("SUPABASE_KEY")

    if supabase_url and supabase_key:
        try:
            from supabase import create_client
            from datetime import timedelta
            supabase = create_client(supabase_url, supabase_key)
            time_threshold = (datetime.utcnow() - timedelta(hours=since_hours)).isoformat()

            query = supabase.table('observations').select('*').gte('observed_at', time_threshold)
            if district_id:
                query = query.eq('district_id', district_id)
            res = query.limit(limit).execute()

            if res.data:
                return {
                    "observations": res.data,
                    "total": len(res.data),
                    "generated_at": datetime.utcnow().isoformat() + "Z",
                    "source": "Supabase"
                }
        except Exception as e:
            print(f"Error fetching observations from Supabase: {e}")

    # Fallback dynamic mock if Supabase is unavailable
    random.seed(datetime.utcnow().hour)
    obs1_fires = random.randint(5, 25)
    obs2_fires = random.randint(1, 10)

    return {
        "observations": [
            {
                "id": str(uuid.uuid4()),
                "district_id": "b0e42d71-55e1-4c12-9c44-59e51c88820c",
                "district_name": "Kostanay",
                "observed_at": datetime.utcnow().isoformat() + "Z",
                "fusion_score": round(random.uniform(70.0, 95.0), 1),
                "risk_level": "CRITICAL",
                "ndvi_mean": 0.12,
                "dnbr_mean": 0.35,
                "bai_max": 1450.5,
                "sar_change_mean": 0.28,
                "active_fire_points": obs1_fires,
                "lat": 53.21,
                "lng": 63.63
            },
            {
                "id": str(uuid.uuid4()),
                "district_id": "c1f53e82-66f2-5d23-0d55-60f62d99931d",
                "district_name": "Akmola",
                "observed_at": datetime.utcnow().isoformat() + "Z",
                "fusion_score": round(random.uniform(50.0, 75.0), 1),
                "risk_level": "HIGH" if random.random() > 0.5 else "MODERATE",
                "ndvi_mean": 0.18,
                "dnbr_mean": 0.21,
                "bai_max": 900.0,
                "sar_change_mean": 0.15,
                "active_fire_points": obs2_fires,
                "lat": 51.18,
                "lng": 71.44
            }
        ],
        "total": 2,
        "generated_at": datetime.utcnow().isoformat() + "Z",
        "source": "Mock (Dynamic)"
    }

@app.get("/api/predictions")
def get_predictions(district_id: str = None, horizon: int = 48):
    seed = sum(ord(c) for c in (district_id or "default"))
    random.seed(seed)

    base_prob = random.uniform(10, 30)
    timeline = [
        {"time": "Now", "prob": int(base_prob)},
        {"time": "+12h", "prob": int(min(100, base_prob + random.uniform(10, 25)))},
        {"time": "+24h", "prob": int(min(100, base_prob + random.uniform(30, 50)))},
        {"time": "+48h", "prob": int(min(100, base_prob + random.uniform(50, 70)))}
    ]
    prob_48 = timeline[-1]["prob"] / 100.0

    return {
        "predictions": [
            {
                "district_id": district_id,
                "district_name": "Dynamic",
                "horizon_hours": horizon,
                "spread_probability": prob_48,
                "risk_level": "CRITICAL" if prob_48 > 0.8 else "HIGH" if prob_48 > 0.5 else "MODERATE",
                "predicted_area_ha": int(random.uniform(500, 5000)),
                "confidence_score": random.uniform(0.7, 0.95),
                "wind_speed_ms": round(random.uniform(5.0, 20.0), 1),
                "wind_dir_deg": random.randint(0, 359),
                "predicted_at": datetime.utcnow().isoformat() + "Z",
                "timeline": timeline
            }
        ]
    }

@app.get("/api/weather/{district_id}")
def get_weather(district_id: str):
    # Try to find the district's lat/lng from our observations
    obs_data = get_observations()
    lat, lng = 51.18, 71.44 # Default to Astana
    for obs in obs_data.get("observations", []):
        if obs.get("district_id") == district_id:
            lat = obs.get("lat", lat)
            lng = obs.get("lng", lng)
            break

    try:
        url = f"https://api.open-meteo.com/v1/forecast?latitude={lat}&longitude={lng}&current=temperature_2m,relative_humidity_2m,wind_speed_10m,wind_direction_10m&hourly=temperature_2m,wind_speed_10m&forecast_days=2"
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
        data = resp.json()
        current = data.get("current", {})
        hourly = data.get("hourly", {})

        forecast = []
        if hourly:
            temps = hourly.get("temperature_2m", [])
            winds = hourly.get("wind_speed_10m", [])
            for i in range(min(48, len(temps))):
                forecast.append({
                    "hour": i,
                    "temp": temps[i],
                    "wind": winds[i]
                })

        return {
            "wind_speed_ms": current.get("wind_speed_10m", 0),
            "wind_dir_deg": current.get("wind_direction_10m", 0),
            "temperature_c": current.get("temperature_2m", 0),
            "humidity_pct": current.get("relative_humidity_2m", 0),
            "forecast_48h": forecast
        }
    except Exception as e:
        print(f"Error fetching weather from Open-Meteo: {e}")
        # Deterministic mock fallback
        seed = sum(ord(c) for c in district_id)
        random.seed(seed)
        temp = round(random.uniform(20.0, 38.0), 1)
        wind = round(random.uniform(2.0, 25.0), 1)
        humidity = round(random.uniform(10.0, 60.0), 1)
        return {
            "wind_speed_ms": wind,
            "wind_dir_deg": random.randint(0, 359),
            "temperature_c": temp,
            "humidity_pct": humidity,
            "forecast_48h": [
                {"hour": i, "temp": temp - (i % 5), "wind": wind + (i % 3)} for i in range(48)
            ]
        }

